#!/usr/bin/env bash
# Writes trading-platform/.env with fresh random secrets for local development.
# Nothing is committed: .env is git-ignored. Re-running keeps an existing file.
set -euo pipefail
cd "$(dirname "$0")/.."

if [ -f .env ]; then
  echo ".env already exists; leaving it alone. Delete it to generate new secrets."
  exit 0
fi

rand() { python3 -c "import secrets; print(secrets.token_urlsafe($1))"; }
key()  { python3 -c "import base64, os; print(base64.b64encode(os.urandom(32)).decode())"; }

umask 077
cat > .env <<ENV
# Generated by scripts/dev-env.sh for local development. Do not commit.
APP_NAME=TradeBridge
POSTGRES_SUPERUSER_PASSWORD=$(rand 24)
OWNER_DB_PASSWORD=$(rand 24)
APP_DB_PASSWORD=$(rand 24)
SECRET_KEY=$(rand 48)
DATA_ENCRYPTION_KEYS=k1:$(key)
DATA_ENCRYPTION_ACTIVE_KEY=k1
ENV
echo "Wrote .env. Start the stack with: docker compose up --build"
